mapper.update:
UPDATE `cors`.`shop_info`
SET
shop_name = #{info.shopName},
shop_time = #{info.shopTime},
shop_category = #{info.shopCategory},
shop_address = #{info.shopAddress},
shop_tel = #{info.shopTel}

    , profile_image = #{info.profileImage}


    , background_image = #{info.backgroundImage}

WHERE user_email = #{info.userEmail}

mapper.select:
SELECT shop_id AS shopId, user_email AS userEmail, shop_name AS shopName, shop_time AS shopTime, shop_category AS shopCategory, shop_address AS shopAddress, shop_tel AS shopTel, profile_image AS profileImage, background_image AS backgroundImage FROM `cors`.`shop_info` WHERE shop_category IN
#{category}
ORDER BY `shopId` DESC
